sys_ui_context_menu.action_script:
var nsProTaskMain;

nsProTaskMain = parent.top.window.gsft_main;

moveProposedToCurrent();

function moveProposedToCurrent(){

	var selected;
	selected = g_list.getChecked();
	if(selected.length == 0)
	{
		selected = g_sysId;
	}
	var circuit = new GlideAjax('x_g_sonc_ns_pro.circuit_ajax');
	circuit.addParam('sysparm_name', 'removeProposedLocalCircuits');
	circuit.addParam('sysparm_selectedCircuits', selected);
	circuit.getXMLAnswer(getResponse);

    function getResponse(response) {
		alert(response);
        var responseObj = JSON.parse(response);
        if (responseObj.resultCode == 'success') {
			nsProTaskMain.g_form.addInfoMessage(responseObj.message);
        } else {
            nsProTaskMain.g_form.addErrorMessage(responseObj.message);
        }
        gsftSubmit(null, nsProTaskMain.g_form.getFormElement(), 'sysverb_update_and_stay');
    }

}

sys_ui_context_menu.on_show_script:
canBeConfigured();

function canBeConfigured() {

    var proposed = false;
	related = g_list.getRelated();

    if (related == "REL:5ea9196387a95a10f9f20f280cbb358c" ) {
        proposed = true;
    }
    if (proposed) {
        g_menu.setEnabled(g_item);
        g_menu.setLabel(g_item, "<b style='color:Tomato;'>• Remove Proposed Circuits •</b>");

    } else {
        g_menu.setDisabled(g_item);
    }

}
